// Studio-clear 12,000 Hz 16-bit signed mono PCM voice clips synthesized via Microsoft Zira Desktop.
// Android delivers packaged voice notifications through native alarms while locked.
// Browser timers are a foreground fallback; no audio starts merely by opening the app.

const SAMPLE_RATE = 12000;
const BYTES_PER_SAMPLE = 2;
const BYTES_PER_SECOND = SAMPLE_RATE * BYTES_PER_SAMPLE; // 24,000 bytes/sec
const MILESTONE_BLOCK_SECONDS = 2;
const MILESTONE_BLOCK_SAMPLES = SAMPLE_RATE * MILESTONE_BLOCK_SECONDS; // 24,000 samples

const VOICE_CLIPS_12K_16BIT_B64 = {
  "ot_0": "",
  "ot_1": "",
  "ot_2": "",
  "ot_3": "",
  "ot_4": "",
  "ot_5": "",
  "ot_6": "",
  "ot_7": "",
  "ot_8": ""
};

const decodedClipInt16Cache = {};
const milestoneBlockBytesCache = {};
let keepAlive1sBytes = null;
let keepAlive60sBytes = null;

let countdownAudioEl = null;
let countdownBlobUrl = '';
let scheduleStartWallMs = 0;
let activeScheduleSignature = '';
let activeScheduledMilestones = [];
let activeOnMilestoneCallback = null;
let isLockTestRunning = false;
let lastShiftScheduleParams = null;

let directVoiceAudioEl = null;
let directVoiceBlobUrl = '';
let sharedVoiceCtx = null;
let backgroundTickerWorker = null;
let workerTickListeners = new Set();
let unlockListenersBound = false;
let lastSpokenWallMs = 0;

function decodeClipToInt16(clipKey) {
  const key = VOICE_CLIPS_12K_16BIT_B64[clipKey] ? clipKey : 'ot_0';
  if (decodedClipInt16Cache[key]) return decodedClipInt16Cache[key];
  try {
    const b64 = VOICE_CLIPS_12K_16BIT_B64[key] || '';
    const bin = typeof atob === 'function' ? atob(b64) : '';
    const byteLen = bin.length - (bin.length % 2);
    const buf = new ArrayBuffer(byteLen);
    const u8 = new Uint8Array(buf);
    for (let i = 0; i < byteLen; i++) {
      u8[i] = bin.charCodeAt(i) & 0xff;
    }
    const i16 = new Int16Array(buf);
    decodedClipInt16Cache[key] = i16;
    return i16;
  } catch (_) {
    return new Int16Array(0);
  }
}

// Builds a single 2.00s (48,000-byte) 16-bit PCM block:
// [0.20s soft chime] + [0.05s gap] + [1x clear 16-bit voice clip] + [padding to 2.00s]
function getMilestonePcmBytes(milestoneHour = 0) {
  const cleanHour = Math.max(0, Math.min(8, Math.round(Number(milestoneHour) || 0)));
  const clipKey = `ot_${cleanHour}`;
  if (milestoneBlockBytesCache[clipKey]) return milestoneBlockBytesCache[clipKey];

  const voiceSamples = decodeClipToInt16(clipKey);
  const blockInt16 = new Int16Array(MILESTONE_BLOCK_SAMPLES);

  // 1. Gentle 0.20s two-note chime (587.33 Hz D5 -> 880 Hz A5) BEFORE the voice (never overlapping!)
  const chimeLen = Math.floor(SAMPLE_RATE * 0.20);
  const gapLen = Math.floor(SAMPLE_RATE * 0.05);
  for (let i = 0; i < chimeLen; i++) {
    const t = i / SAMPLE_RATE;
    const freq = t < 0.095 ? 587.33 : 880.0;
    const fadeIn = Math.min(1, i / (SAMPLE_RATE * 0.012));
    const env = Math.exp(-t * 8.5) * fadeIn;
    const val = Math.sin(2 * Math.PI * freq * t) * 0.26 * env;
    blockInt16[i] = Math.max(-32767, Math.min(32767, Math.round(val * 32767)));
  }

  // 2. Single 1x crystal-clear 16-bit voice clip (NEVER repeated 3 times)
  const voiceOffset = chimeLen + gapLen;
  const maxCopy = Math.min(voiceSamples.length, MILESTONE_BLOCK_SAMPLES - voiceOffset);
  for (let i = 0; i < maxCopy; i++) {
    blockInt16[voiceOffset + i] = voiceSamples[i];
  }

  const bytes = new Uint8Array(blockInt16.buffer, blockInt16.byteOffset, blockInt16.byteLength);
  milestoneBlockBytesCache[clipKey] = bytes;
  return bytes;
}

// 16 Hz infrasound sine wave at -29.5 dBFS (amplitude 1100 / 32768).
// At 12,000 Hz, 16 Hz has an exact period of 750 samples, so 1s (12,000 samples) = 16.0000 exact cycles.
// Completely inaudible on phone speakers (0 harmonics, <20 Hz infrasound), yet prevents Android AudioTrack
// and Chromium SilentSinkSuspender from sleeping when the screen is turned off.
function ensureKeepAliveChunks() {
  if (keepAlive1sBytes && keepAlive60sBytes) return;
  const oneSecInt16 = new Int16Array(SAMPLE_RATE);
  const twoPi16 = (2 * Math.PI * 16) / SAMPLE_RATE;
  for (let i = 0; i < SAMPLE_RATE; i++) {
    oneSecInt16[i] = Math.round(Math.sin(twoPi16 * i) * 1100);
  }
  keepAlive1sBytes = new Uint8Array(oneSecInt16.buffer);

  const sixtySecInt16 = new Int16Array(SAMPLE_RATE * 60);
  for (let s = 0; s < 60; s++) {
    sixtySecInt16.set(oneSecInt16, s * SAMPLE_RATE);
  }
  keepAlive60sBytes = new Uint8Array(sixtySecInt16.buffer);
}

function createWavHeaderBytes(totalDataByteLength) {
  const header = new Uint8Array(44);
  const view = new DataView(header.buffer);
  const writeAscii = (offset, str) => {
    for (let i = 0; i < str.length; i++) header[offset + i] = str.charCodeAt(i);
  };
  writeAscii(0, 'RIFF');
  view.setUint32(4, 36 + totalDataByteLength, true);
  writeAscii(8, 'WAVE');
  writeAscii(12, 'fmt ');
  view.setUint32(16, 16, true); // PCM chunk size
  view.setUint16(20, 1, true);  // AudioFormat = 1 (PCM)
  view.setUint16(22, 1, true);  // NumChannels = 1 (Mono)
  view.setUint32(24, SAMPLE_RATE, true);
  view.setUint32(28, BYTES_PER_SECOND, true);
  view.setUint16(32, BYTES_PER_SAMPLE, true);
  view.setUint16(34, 16, true); // BitsPerSample = 16
  writeAscii(36, 'data');
  view.setUint32(40, totalDataByteLength, true);
  return header;
}

function buildStandaloneMilestoneWavBlob(milestoneHour = 0) {
  const pcmBytes = getMilestonePcmBytes(milestoneHour);
  const header = createWavHeaderBytes(pcmBytes.byteLength);
  if (typeof Blob !== 'undefined') {
    return new Blob([header, pcmBytes], { type: 'audio/wav' });
  }
  return null;
}

function buildStandaloneMilestoneDataUri(milestoneHour = 0) {
  try {
    const pcmBytes = getMilestonePcmBytes(milestoneHour);
    const header = createWavHeaderBytes(pcmBytes.byteLength);
    const wav = new Uint8Array(header.byteLength + pcmBytes.byteLength);
    wav.set(header, 0);
    wav.set(pcmBytes, 44);
    let bin = '';
    const chunk = 8192;
    for (let i = 0; i < wav.length; i += chunk) {
      bin += String.fromCharCode.apply(null, wav.subarray(i, i + chunk));
    }
    return 'data:audio/wav;base64,' + btoa(bin);
  } catch (_) {
    return '';
  }
}

function getOrInitAudioContext() {
  if (typeof window === 'undefined') return null;
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx) return null;
  if (!sharedVoiceCtx || sharedVoiceCtx.state === 'closed') {
    try {
      sharedVoiceCtx = new AudioCtx();
    } catch (_) {
      return null;
    }
  }
  return sharedVoiceCtx;
}

function nativeOtBridge() {
  if (typeof window === 'undefined') return null;
  const bridge = window.PattanBiometric || window.PattanBiometricBridge;
  return bridge && typeof bridge.scheduleOtMilestones === 'function' ? bridge : null;
}

export function forceRaisePhoneSpeakerVolume() {
  // Compatibility export. Reminders respect the phone owner's volume and DND settings.
  return false;
}

function isCountdownCurrentlySpeakingMilestone(milestoneHour, includeAlreadyPassedOnStream = false) {
  if (!countdownAudioEl || countdownAudioEl.paused) return false;
  const curSec = Number(countdownAudioEl.currentTime) || 0;
  for (const m of activeScheduledMilestones) {
    if (milestoneHour === undefined || m.hour === milestoneHour) {
      if (includeAlreadyPassedOnStream) {
        if (curSec >= m.wavStartSec - 2.5) {
          return true;
        }
      } else if (curSec >= m.wavStartSec - 2.5 && curSec <= m.wavEndSec + 2.5) {
        return true;
      }
    }
  }
  return false;
}

function stopCountdownAudioStreamOnly() {
  if (countdownAudioEl) {
    try {
      countdownAudioEl.pause();
      countdownAudioEl.removeAttribute('src');
      countdownAudioEl.load();
    } catch (_) {}
  }
  if (countdownBlobUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
    try {
      URL.revokeObjectURL(countdownBlobUrl);
    } catch (_) {}
    countdownBlobUrl = '';
  }
}

function syncAndCheckScheduledMilestones() {
  if (!activeScheduledMilestones.length || scheduleStartWallMs <= 0) return;
  const nowMs = Date.now();
  const elapsedWallSec = Math.max(0, (nowMs - scheduleStartWallMs) / 1000);

  // Only keep countdownAudioEl playing during an explicit 6-second Lock-Screen Voice Test.
  // NEVER play a continuous HTML5 <audio> element during normal shift/OT tracking, because
  // HTML5 <audio>.play() requests Android AUDIOFOCUS_GAIN and pauses Spotify / YouTube Music!
  if (isLockTestRunning && countdownAudioEl && !countdownAudioEl.paused) {
    const audioSec = Number(countdownAudioEl.currentTime) || 0;
    const duration = Number(countdownAudioEl.duration) || 0;
    const speakingNow = isCountdownCurrentlySpeakingMilestone(undefined, false);
    if (!speakingNow && duration > 0 && elapsedWallSec < duration - 0.5 && Math.abs(audioSec - elapsedWallSec) > 2.5) {
      try {
        countdownAudioEl.currentTime = elapsedWallSec;
      } catch (_) {}
    }
  } else if (isLockTestRunning && countdownAudioEl && countdownAudioEl.paused && activeScheduledMilestones.some((m) => m.isLockTest && !m.fired)) {
    try {
      if (elapsedWallSec > 0.5) {
        countdownAudioEl.currentTime = elapsedWallSec;
      }
      countdownAudioEl.play().catch(() => {});
    } catch (_) {}
  }

  for (const m of activeScheduledMilestones) {
    if (m.fired) continue;
    if (!m.volumeBoosted && nowMs >= m.epochMs - 1500) {
      m.volumeBoosted = true;
      forceRaisePhoneSpeakerVolume();
    }
    if (nowMs >= m.epochMs) {
      m.fired = true;
      forceRaisePhoneSpeakerVolume();
      const alreadyHandledByContinuousStream = isLockTestRunning && isCountdownCurrentlySpeakingMilestone(m.hour, true);
      if (!alreadyHandledByContinuousStream) {
        speakOtMilestoneOutLoud(m.hour, { fromScheduleFallback: true });
      } else {
        lastSpokenWallMs = nowMs;
      }
      if (m.isLockTest) {
        isLockTestRunning = false;
        setTimeout(() => {
          stopCountdownAudioStreamOnly();
        }, 2400);
        if (typeof m.onLockTestTrigger === 'function') {
          try {
            m.onLockTestTrigger();
          } catch (_) {}
        }
      } else if (typeof activeOnMilestoneCallback === 'function') {
        try {
          activeOnMilestoneCallback(m);
        } catch (_) {}
      }
    }
  }
}

function ensureBackgroundWorkerRunning() {
  if (typeof window === 'undefined' || typeof Worker === 'undefined' || typeof Blob === 'undefined') return;
  if (backgroundTickerWorker) return;
  try {
    const workerCode = `
      setInterval(function() {
        postMessage({ type: 'tick', nowMs: Date.now() });
      }, 1000);
    `;
    const blob = new Blob([workerCode], { type: 'application/javascript' });
    const url = URL.createObjectURL(blob);
    backgroundTickerWorker = new Worker(url);
    backgroundTickerWorker.onmessage = () => {
      try {
        syncAndCheckScheduledMilestones();
        workerTickListeners.forEach((fn) => {
          try {
            fn(new Date());
          } catch (_) {}
        });
      } catch (_) {}
    };
  } catch (_) {}
}

export function subscribeBackgroundClockTick(listener) {
  if (typeof listener !== 'function') return () => {};
  ensureVoiceAudioUnlocked();
  workerTickListeners.add(listener);
  return () => {
    workerTickListeners.delete(listener);
  };
}

export function stopScheduledVoiceAlarms() {
  try { nativeOtBridge()?.cancelOtMilestones?.(); } catch (_) {}
  activeScheduleSignature = '';
  activeScheduledMilestones = [];
  activeOnMilestoneCallback = null;
  lastShiftScheduleParams = null;
  scheduleStartWallMs = 0;
  isLockTestRunning = false;
  if (countdownAudioEl) {
    try {
      countdownAudioEl.pause();
      countdownAudioEl.removeAttribute('src');
      countdownAudioEl.load();
    } catch (_) {}
  }
  if (countdownBlobUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
    try {
      URL.revokeObjectURL(countdownBlobUrl);
    } catch (_) {}
    countdownBlobUrl = '';
  }
}

function startBakedScheduleWav(milestones, signature, onMilestoneTrigger) {
  if (typeof window === 'undefined' || typeof Audio === 'undefined' || typeof Blob === 'undefined') return;
  ensureKeepAliveChunks();

  const nowMs = Date.now();
  const blobParts = [new Uint8Array(44)]; // placeholder for 44-byte WAV header
  let cursorSec = 0;
  const builtMilestones = [];

  for (const m of milestones) {
    const targetSec = Math.max(cursorSec + 1, Math.round((m.epochMs - nowMs) / 1000));
    const gapSec = Math.max(0, targetSec - cursorSec);
    const minsCount = Math.floor(gapSec / 60);
    const remSecsCount = gapSec % 60;

    for (let i = 0; i < minsCount; i++) {
      blobParts.push(keepAlive60sBytes);
    }
    for (let i = 0; i < remSecsCount; i++) {
      blobParts.push(keepAlive1sBytes);
    }

    const voiceBlockBytes = getMilestonePcmBytes(m.hour);
    blobParts.push(voiceBlockBytes);

    builtMilestones.push({
      ...m,
      wavStartSec: targetSec,
      wavEndSec: targetSec + MILESTONE_BLOCK_SECONDS,
      fired: false,
    });
    cursorSec = targetSec + MILESTONE_BLOCK_SECONDS;
  }

  // Add 2s trailing pad so onended never clips the last word
  blobParts.push(keepAlive1sBytes);
  blobParts.push(keepAlive1sBytes);
  cursorSec += 2;

  const totalDataBytes = cursorSec * BYTES_PER_SECOND;
  blobParts[0] = createWavHeaderBytes(totalDataBytes);

  if (countdownBlobUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
    try {
      URL.revokeObjectURL(countdownBlobUrl);
    } catch (_) {}
    countdownBlobUrl = '';
  }

  const wavBlob = new Blob(blobParts, { type: 'audio/wav' });
  countdownBlobUrl = URL.createObjectURL(wavBlob);
  scheduleStartWallMs = nowMs;
  activeScheduleSignature = signature;
  activeScheduledMilestones = builtMilestones;
  activeOnMilestoneCallback = typeof onMilestoneTrigger === 'function' ? onMilestoneTrigger : null;

  if (!countdownAudioEl) {
    countdownAudioEl = new Audio();
    countdownAudioEl.preload = 'auto';
    countdownAudioEl.addEventListener('timeupdate', () => {
      syncAndCheckScheduledMilestones();
    });
    countdownAudioEl.addEventListener('ended', () => {
      syncAndCheckScheduledMilestones();
      if (isLockTestRunning) {
        isLockTestRunning = false;
        activeScheduleSignature = '';
      }
    });
  }

  countdownAudioEl.loop = false;
  countdownAudioEl.volume = 1.0;
  countdownAudioEl.src = countdownBlobUrl;
  try {
    const p = countdownAudioEl.play();
    if (p && typeof p.catch === 'function') {
      p.catch(() => {});
    }
  } catch (_) {}
}

// Arms the full sequence of voice milestones from Shift End (0h = "Your time has completed")
// through every 1 hour of OT (1h = "1 hour completed", 2h = "2 hours completed", ..., up to 8h)
// until the user punches OUT (logs out).
export function armShiftAndOtMilestonesSchedule({
  shiftEndEpochMs = 0,
  dateKey = '',
  alreadySpokenHours = [],
  onMilestoneTrigger = null,
} = {}) {
  if (typeof window === 'undefined') return;
  ensureVoiceAudioUnlocked();

  const baseEpochMs = Number(shiftEndEpochMs) || 0;
  if (baseEpochMs <= 0 || !dateKey) {
    stopScheduledVoiceAlarms();
    return;
  }

  const native = nativeOtBridge();
  if (native) {
    // Native alarms own delivery and deduplication. Do not run a second audio timer.
    activeScheduledMilestones = [];
    stopCountdownAudioStreamOnly();
    return native.scheduleOtMilestones(JSON.stringify({
      shiftEndEpochMs: baseEpochMs, dateKey, alreadySpokenHours,
    }));
  }

  lastShiftScheduleParams = {
    shiftEndEpochMs: baseEpochMs,
    dateKey,
    alreadySpokenHours: Array.isArray(alreadySpokenHours) ? [...alreadySpokenHours] : [],
    onMilestoneTrigger,
  };

  // Do not overwrite an active 6-second Lock Test while it is counting down
  if (isLockTestRunning) return;

  const spokenSet = new Set(Array.isArray(alreadySpokenHours) ? alreadySpokenHours.map((h) => Number(h)) : []);
  const shiftSignature = `${dateKey}@${baseEpochMs}`;

  if (shiftSignature === activeScheduleSignature && activeScheduledMilestones.length > 0) {
    activeOnMilestoneCallback = typeof onMilestoneTrigger === 'function' ? onMilestoneTrigger : null;
    for (const m of activeScheduledMilestones) {
      if (spokenSet.has(m.hour)) {
        m.fired = true;
      }
    }
    if (activeScheduledMilestones.every((m) => m.fired)) {
      stopScheduledVoiceAlarms();
    }
    return;
  }

  const nowMs = Date.now();
  const upcoming = [];

  for (let h = 0; h <= 8; h++) {
    if (spokenSet.has(h)) continue;
    const mEpochMs = baseEpochMs + h * 3600 * 1000;
    // Include milestones in the future (or within the last 1.5s if just reached)
    if (mEpochMs >= nowMs - 1500) {
      upcoming.push({
        hour: h,
        epochMs: mEpochMs,
        milestoneKey: `${dateKey}_ot_${h}`,
      });
    }
  }

  if (!upcoming.length) {
    stopScheduledVoiceAlarms();
    return;
  }

  // Track milestones silently via the background Web Worker + native Android AlarmManager
  // WITHOUT starting a continuous HTML5 <audio> stream, so background music (Spotify / YouTube Music)
  // is NEVER paused when opening or using the Salary & OT app!
  stopCountdownAudioStreamOnly();
  scheduleStartWallMs = nowMs;
  activeScheduleSignature = shiftSignature;
  activeScheduledMilestones = upcoming.map((m) => ({
    ...m,
    wavStartSec: Math.max(1, Math.round((m.epochMs - nowMs) / 1000)),
    wavEndSec: Math.max(1, Math.round((m.epochMs - nowMs) / 1000)) + MILESTONE_BLOCK_SECONDS,
    fired: false,
  }));
  activeOnMilestoneCallback = typeof onMilestoneTrigger === 'function' ? onMilestoneTrigger : null;
}

// Legacy single-alarm wrapper (delegates to armShiftAndOtMilestonesSchedule)
export function armShiftEndVoiceAlarm({ targetEpochMs = 0, dateKey = '', onTrigger = null } = {}) {
  armShiftAndOtMilestonesSchedule({
    shiftEndEpochMs: targetEpochMs,
    dateKey,
    alreadySpokenHours: [],
    onMilestoneTrigger: (m) => {
      if (m.hour === 0 && typeof onTrigger === 'function') {
        onTrigger(dateKey);
      }
    },
  });
}

// Speaks a specific milestone ONCE (0 = "Your time has completed.", 1 = "1 hour completed.", 2 = "2 hours completed.", etc.)
export function speakOtMilestoneOutLoud(milestoneHour = 0, options = {}) {
  if (typeof window === 'undefined') return false;
  const native = nativeOtBridge();
  if (native) return native.speakOtMilestone(Math.max(0, Math.min(8, Math.round(Number(milestoneHour) || 0))));
  ensureVoiceAudioUnlocked();
  forceRaisePhoneSpeakerVolume();

  const nowMs = Date.now();
  const cleanHour = Math.max(0, Math.min(8, Math.round(Number(milestoneHour) || 0)));

  // Deduplicate: never allow two overlapping voice playbacks within 3.5 seconds
  if (nowMs - lastSpokenWallMs < 3500) {
    return true;
  }
  // If the pre-baked countdown <audio> element is ALREADY playing (or already played on the continuous stream) this milestone, do not double-play!
  if (
    !options?.fromScheduleFallback &&
    isCountdownCurrentlySpeakingMilestone(cleanHour, Boolean(options?.fromMilestoneTrigger))
  ) {
    lastSpokenWallMs = nowMs;
    return true;
  }
  lastSpokenWallMs = nowMs;

  // Primary: Play 1x 16-bit PCM via Web Audio API (AudioContext) first so it mixes with
  // Spotify / YouTube Music without stealing Android MediaSession audio focus!
  if (playViaWebAudioFallback(cleanHour)) {
    return true;
  }

  // Fallback: HTML5 <audio> element only if Web Audio API is unavailable
  if (typeof Audio !== 'undefined') {
    try {
      if (!directVoiceAudioEl) {
        directVoiceAudioEl = new Audio();
        directVoiceAudioEl.preload = 'auto';
      }
      if (directVoiceBlobUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
        try {
          URL.revokeObjectURL(directVoiceBlobUrl);
        } catch (_) {}
        directVoiceBlobUrl = '';
      }
      const blob = buildStandaloneMilestoneWavBlob(cleanHour);
      const srcUrl = blob && typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function'
        ? (directVoiceBlobUrl = URL.createObjectURL(blob))
        : buildStandaloneMilestoneDataUri(cleanHour);

      if (srcUrl) {
        directVoiceAudioEl.pause();
        directVoiceAudioEl.src = srcUrl;
        directVoiceAudioEl.currentTime = 0;
        directVoiceAudioEl.volume = 1.0;
        const playPromise = directVoiceAudioEl.play();
        if (playPromise && typeof playPromise.catch === 'function') {
          playPromise.catch(() => {});
        }
        return true;
      }
    } catch (_) {}
  }

  return false;
}

function playViaWebAudioFallback(cleanHour = 0) {
  try {
    const ctx = getOrInitAudioContext();
    if (!ctx) return false;
    if (ctx.state === 'suspended') {
      ctx.resume().catch(() => {});
    }
    const pcmBytes = getMilestonePcmBytes(cleanHour);
    const int16 = new Int16Array(pcmBytes.buffer, pcmBytes.byteOffset, pcmBytes.byteLength / 2);
    const audioBuffer = ctx.createBuffer(1, int16.length, SAMPLE_RATE);
    const channel = audioBuffer.getChannelData(0);
    for (let i = 0; i < int16.length; i++) {
      channel[i] = int16[i] / 32768.0;
    }
    const src = ctx.createBufferSource();
    src.buffer = audioBuffer;
    const gain = ctx.createGain();
    gain.gain.value = 1.35;
    src.connect(gain);
    gain.connect(ctx.destination);
    src.onended = () => {
      try {
        if (ctx && ctx.state === 'running') {
          ctx.suspend().catch(() => {});
        }
      } catch (_) {}
    };
    src.start(0);
    return true;
  } catch (_) {
    return false;
  }
}

export function speakTimeCompletedOutLoud(options = {}) {
  return speakOtMilestoneOutLoud(0, options);
}

export function ensureVoiceAudioUnlocked() {
  if (typeof window === 'undefined') return;
  ensureBackgroundWorkerRunning();

  if (unlockListenersBound) return;
  unlockListenersBound = true;

  const onUserInteractionOrVisibility = () => {
    try {
      ensureBackgroundWorkerRunning();
      if (isLockTestRunning && countdownAudioEl && countdownAudioEl.paused && activeScheduledMilestones.some((m) => m.isLockTest && !m.fired)) {
        const elapsedSec = Math.max(0, (Date.now() - scheduleStartWallMs) / 1000);
        if (elapsedSec > 0.5) {
          try {
            countdownAudioEl.currentTime = elapsedSec;
          } catch (_) {}
        }
        countdownAudioEl.play().catch(() => {});
      }
      syncAndCheckScheduledMilestones();
    } catch (_) {}
  };

  ['pointerdown', 'touchstart', 'click', 'keydown'].forEach((evt) => {
    window.addEventListener(evt, onUserInteractionOrVisibility, { passive: true, capture: true });
  });

  if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', onUserInteractionOrVisibility);
  }
}

// 1-Tap Lock-Screen Voice Test: immediately starts a pre-baked 16-bit WAV with 6 seconds of
// inaudible 16 Hz lead-in followed by 1x "Your time has completed." AND seamlessly appends
// all upcoming Shift End + Hourly OT milestones (0h..8h) in the same continuous WAV stream
// so that even if the user leaves their phone locked after the test, every hour still announces!
export function scheduleLockScreenVoiceTestInSeconds(seconds = 6, onTrigger = null) {
  if (typeof window === 'undefined') return;
  const native = nativeOtBridge();
  if (native) return native.testOtMilestoneInSeconds(Math.max(2, Math.round(Number(seconds) || 6)));
  ensureVoiceAudioUnlocked();
  const delaySec = Math.max(2, Math.round(Number(seconds) || 6));
  const targetEpochMs = Date.now() + delaySec * 1000;
  isLockTestRunning = true;

  const combinedMilestones = [
    {
      hour: 0,
      epochMs: targetEpochMs,
      milestoneKey: `lock_test_${targetEpochMs}`,
      isLockTest: true,
      onLockTestTrigger: onTrigger,
    },
  ];

  let nextSignature = `lock_test_${targetEpochMs}`;
  let shiftCallback = null;

  if (lastShiftScheduleParams && lastShiftScheduleParams.shiftEndEpochMs > 0 && lastShiftScheduleParams.dateKey) {
    const { shiftEndEpochMs, dateKey, alreadySpokenHours, onMilestoneTrigger } = lastShiftScheduleParams;
    const spokenSet = new Set(Array.isArray(alreadySpokenHours) ? alreadySpokenHours.map((h) => Number(h)) : []);
    for (let h = 0; h <= 8; h++) {
      if (spokenSet.has(h)) continue;
      const mEpochMs = shiftEndEpochMs + h * 3600 * 1000;
      if (mEpochMs > targetEpochMs + 4000) {
        combinedMilestones.push({
          hour: h,
          epochMs: mEpochMs,
          milestoneKey: `${dateKey}_ot_${h}`,
        });
      }
    }
    nextSignature = `${dateKey}@${shiftEndEpochMs}`;
    shiftCallback = onMilestoneTrigger;
  }

  startBakedScheduleWav(combinedMilestones, nextSignature, shiftCallback);
}
